extern "C" int strlen(const char *);

struct string_buf {
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx {
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  stringx(const char *, int = -1);
  ~stringx();
  void make_room(int);
  void append(const char *, int = -1);
  void append(const stringx &);
  const char *c_str() const { return chars; }
  friend stringx operator+(const stringx &, const stringx &);
};

inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

class entity_track_tree;
class entity_anim_tree;
class ett_manager {
public:
  entity_track_tree *acquire(const stringx &);
};
class world_dynamics_system {
public:
  ett_manager *get_ett_manager();
};
extern world_dynamics_system *g_world_ptr;

class entity_id {
public:
  stringx get_val() const;
};

extern void error(const char *, ...);

class entity {
  char data_before_id[0x80];
  entity_id id;
public:
  stringx get_name() const { return id.get_val(); }
  entity_anim_tree *play_anim(int, const stringx &, const entity_track_tree &, const entity_track_tree &, float, float, float, unsigned short, short);
  entity_anim_tree *play_anim(int, const stringx &, const stringx &, float, float, float, unsigned short, short);
};

entity_anim_tree* entity::play_anim( int slot,
                                     const stringx& filenamea,
                                     const stringx& filenameb,
                                     float blenda,
                                     float blendb,
                                     float start_time,
                                     unsigned short anim_flags,
                                     short loop )
{
  entity_track_tree* tracka = 0;
  entity_track_tree* trackb = 0;

  tracka = g_world_ptr->get_ett_manager()->acquire( filenamea );
  trackb = g_world_ptr->get_ett_manager()->acquire( filenameb );

  if ( tracka == 0)
    error( "%s: play_anim('%s'): must load anim before playing", get_name().c_str(), filenamea.c_str() );
  if ( trackb == 0)
    error( "%s: play_anim('%s'): must load anim before playing", get_name().c_str(), filenameb.c_str() );

  stringx name = stringx("(") + filenamea + "+" + filenameb + stringx(")");
  return play_anim( slot, name, *tracka, *trackb, blenda, blendb, start_time, anim_flags, loop );
}
